      "requires_current_authority_verification": false
    },
    "conflict_93751ecc3dfc7952efe76bd6": {
      "classification": "complementary_or_no_conflict",
      "reason": "Claim 1 details the alleged conduct and tariff rates (2.5% vs 25%) regarding Ford Transit Connects. Claim 2 details the financial settlement ($365 million) resulting from that dispute. They describe different aspects of the same event.",
      "requires_current_authority_verification": false
    },
    "conflict_3ceac8799c018cc9865e0219": {
      "classification": "complementary_or_no_conflict",
      "reason": "Claim 1 describes the settlement terms ($365 million). Claim 2 provides background on the origin/facility (Turkey) of the vehicles involved in the dispute. They provide distinct information about the same case context.",
      "requires_current_authority_verification": false
    },
    "conflict_89d44a54b99294cf6b7e158f": {
      "classification": "different_products_origins_or_programs",
      "reason": "Claim 1 reports enforcement outcomes (fines/reclassifications) for pick-up trucks in Switzerland. Claim 2 cites the HS Committee definition regarding transport of goods. One is country-specific enforcement, the other is a general classification standard.",
      "requires_current_authority_verification": false
    },
    "conflict_266a2a776ce073b760c6d67d": {
      "classification": "different_dates_or_policy_stages",
      "reason": "Claim 1 states implementation effective August 7, 2025. Claim 2 indicates the administration indicated tariffs may be subject under preliminary agreements. This reflects a progression from indication/preliminary status to implementation.",
      "requires_current_authority_verification": false
    },
    "conflict_41d1eb6ffdefae635296fc4e": {
      "classification": "complementary_or_no_conflict",
      "reason": "Claim 1 discusses the risk/mechanism of price adjustment clauses regarding tariff increases. Claim 2 reports supplier intent to pass through 100% of impact. One addresses contractual tools, the other addresses market behavior.",
      "requires_current_authority_verification": false
    },
    "conflict_80c063aa6944a709c0ef2fd2": {
      "classification": "complementary_or_no_conflict",
      "reason": "Claim 1 distinguishes impact on Tier 1 vs Tier 2/3 suppliers. Claim 2 suggests OEMs may support struggling suppliers. Both describe supply chain dynamics under tariff pressure from the same source.",
      "requires_current_authority_verification": false
    },
    "conflict_9e594e4eb601323485aeba0a": {
      "classification": "apparent_same_scope_conflict",
      "reason": "Both claims describe 100% duties on STS cranes from USTR. However, Claim 1 states effective date October 14, 2025, while Claim 2 states April 17, 2025. This is a direct conflict on the effective date for the same product/rate.",
      "requires_current_authority_verification": false
    },
    "conflict_b6e969e36512cc29b2b8e906": {
      "classification": "complementary_or_no_conflict",
      "reason": "Both claims describe the same tariff action (up to 150% on cargo handling equipment) from the same USTR document. Claim 1 includes metadata (announcement date), Claim 2 describes the annex content. They are consistent descriptions of the same policy.",
      "requires_current_authority_verification": false
    },
    "conflict_90bf35e928044ee2c0172674": {
      "classification": "different_products_origins_or_programs",
      "reason": "Claim 1 specifies up to 150% on cargo handling equipment (e.g., rubber tire gantry cranes). Claim 2 specifies 100% on STS cranes and certain cargo handling equipment. These appear to be different duty tiers or product subsets within the same action.",
      "requires_current_authority_verification": false
    }
  }
}
